function buildDeltas(before: Snapshot, after: Snapshot): ITickDeltas {
  const from_poll = multisetDiff(before.from_poll, after.from_poll);
  const from_push = multisetDiff(before.from_push, after.from_push);
  const latest = multisetDiff(before.latest, after.latest);
  return {
    rels: [
      { rel: "from_poll", add: from_poll.add, del: from_poll.del },
      { rel: "from_push", add: from_push.add, del: from_push.del },
      { rel: "latest", add: latest.add, del: latest.del },
    ],
    carryPending: latest.add.length > 0 || latest.del.length > 0,
  };
}

function runNaiveTick(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<ITickDeltas> {
  return readSnapshot(seam).pipe(
    concatMap((before) => applyArrivals(seam, arrivals).pipe(map(() => before))),
    concatMap((before) =>
      forkJoin([resolveLatest_0Writes(seam, before, arrivals), resolveLatest_1Writes(seam, before, arrivals)]).pipe(map((groups) => groups.flat())).pipe(
        concatMap((statements) => seam.runner.batch(seam.db, statements)),
        map(() => before),
      ),
    ),
    concatMap((before) => recomputeLevels(seam).pipe(map(() => before))),
    concatMap((before) => readSnapshot(seam).pipe(map((after) => buildDeltas(before, after)))),
  );
  // key_same_tick_ordered_not_conflict: engine.pl process_occurrences -> level_closure -> boundary_deltas.
}

const INCREMENTAL_PROGRAM_SAFE = true;
const EMITTER_MODE = process.env.SPREFA_TSV2_EMITTER_MODE === "naive" ? "naive" : "incremental";

function runIncrementalTick(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<ITickDeltas> {
  return IncrementalRuntime.clearDeltas(seam, INCREMENTAL_RELATIONS).pipe(
    concatMap(() => IncrementalRuntime.applyArrivals(seam, arrivals, INCREMENTAL_RELATIONS)),
    concatMap(() => IncrementalRuntime.applyEdges(seam, INCREMENTAL_EDGE_STATEMENTS)),
    concatMap(() => IncrementalRuntime.applyLevels(seam, INCREMENTAL_LEVEL_STATEMENTS)),
    concatMap(() => IncrementalRuntime.readBoundary(seam, INCREMENTAL_RELATIONS)),
    map((rels): ITickDeltas => ({
      rels,
      carryPending: rels.some((delta) => ["latest"].includes(delta.rel) && (delta.add.length > 0 || delta.del.length > 0)),
    })),
  );
}

function runTick(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<ITickDeltas> {
  const hasRetraction = arrivals.some((arrival) => arrival.sign === "del");
  if (EMITTER_MODE === "naive" || !INCREMENTAL_PROGRAM_SAFE || hasRetraction) {
    return runNaiveTick(seam, arrivals);
  }
  return runIncrementalTick(seam, arrivals);
}

